import itertools

def get_connected_pairs(pairs):
    adj = {}
    for s, b in pairs:
        adj[s] = b
    connected_pairs = set()
    visited = set()
    all_b = set(b for s, b in pairs)
    all_s = set(s for s, b in pairs)
    starts = all_s - all_b
    for s in starts:
        path = []
        curr = s
        while curr in adj:
            path.append(curr)
            visited.add(curr)
            curr = adj[curr]
        path.append(curr)
        for i in range(len(path)):
            for j in range(i + 1, len(path)):
                connected_pairs.add((path[i], path[j]))
    return connected_pairs

def find_disjoint_with_pairs(N, k):
    all_S = []
    all_pairs = []
    for s_indices in itertools.combinations(range(1, N + 1), k):
        for b_indices in itertools.combinations(range(1, N + 1), k):
            valid = True
            for i in range(k):
                if s_indices[i] >= b_indices[i]:
                    valid = False
                    break
            if valid:
                pairs = list(zip(s_indices, b_indices))
                all_pairs.append(pairs)
                all_S.append(get_connected_pairs(pairs))
    for i in range(len(all_S)):
        for j in range(i, len(all_S)):
            if all_S[i].isdisjoint(all_S[j]):
                return all_pairs[i], all_pairs[j], all_S[i], all_S[j]
    return None

